INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(7066, 'koKR', 'Nasiono życia', 'Wyrodne centaury – moi synowie i córki – potrzebują swojego ojca.$B$BRozejrzyj się – to miejsce tchnie nadzieją i wszystkim, czego naucza mój ojciec Cenarius. Wyrosło ze mnie! Nie mogę im tego odebrać... nawet za zbrodnie, których się wobec mnie dopuściły.$B$BJest jednak coś, o co chciałbym cię poprosić, by uspokoić mojego brata. Weź to... to pierwsze nasiono, które spadło z życia wykarmionego moimi szczątkami. Powiedz mu, że mój duch pozostaje tutaj i że żyję nadal. Jestem pewien, że zrozumie.', 'Odszukaj Remulosa w Gaju Luny i daj mu Nasiono życia.', '', '', '', '', '', '', 0),
(8635, 'koKR', 'Nestor Rozłupana Skała', '', '', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(7046, 'koKR', 'Weź to, proszę, i pamiętaj, że moc, którą teraz otrzymujesz, musi służyć dobru. Kontynuuj wędrówkę przez jaskinie, a być może odnajdziesz szczątki mojego wuja. Czeka cię wiele niebezpieczeństw, $N.$B$BPorozmawiaj ze mną ponownie, jeśli zajdzie potrzeba.', 0),
(7066, 'koKR', 'A więc mój brat w końcu zaznał spokoju? Jestem dumny, że dożyłem tego dnia. Przy całej jego arogancji i gniewie naprawdę myślałem, że jest dla nas stracony, ale to... ten symbol jego poświęcenia dowodzi tylko, że nie jest stracony – on się jedynie odrodził. Zajmuje swoje miejsce w naturze, jak nakazywał mu obowiązek.$B$BDziękuję ci, $N. Przynosząc mi to, $gocaliłeś:ocaliłaś; odrobinę nadziei, którą uważałem za utraconą. To nasiono będzie kiedyś ważne dla mieszkańców tej rozdartej wojną krainy... Czuję to.', 0),
(8635, 'koKR', 'Bitwy minionych wieków to nasiona, z których wyrastają legendy. Twoje czasy to czasy bohaterów, dziecko. Oby twoja legenda zapuściła korzenie i rozkwitła.$B$BŻyczę ci wszystkiego dobrego, $N, i ofiarowuję ten dar...', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(7046, 'koKR', 'Jeśli chcesz rozpocząć rytuał od nowa, porzuć naszą pierwszą próbę i porozmawiaj ze mną ponownie.', 0),
(7066, 'koKR', 'Czuć od ciebie woń splugawienia, $N... jak od wielu poszukiwaczy przygód w tych czasach. Ale coś w tobie jest innego. Czy $gprzyszedłeś:przyszłaś; ze mną o czymś porozmawiać? Otacza cię aura, która wydaje się znajoma, ale nie potrafię jej rozpoznać.$B$BProszę, błagam cię, powiedz mi, dlaczego $gszukałeś:szukałaś; u mnie posłuchania.', 0);
