INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8639, 'koKR', '', 'Nie masz czego szukać w tych ogrodach. Twoje ciało odżywi nasze urocze twory!', 0),
(8640, 'koKR', '', 'Nic nie może splugawić ogrodów! Musisz zostać $gzniszczony:zniszczona;!', 0),
(8852, 'koKR', 'Moje! Moje! Moje! Gizlock jest władcą tej domeny! Nigdy nie zdradzisz mojej obecności!', '', 0),
(8921, 'koKR', 'Pozdrawiam cię.', '', 0),
(8922, 'koKR', 'Wolny! Nareszcie wolny od moich więzów!', '', 0);
